def parse(stdin):
    parts = stdin.split()
    assert len(parts) == 2
    return [int(parts[0]), int(parts[1])]

def render(case):
    return f"{case[0]} {case[1]}"

def valid(case):
    return isinstance(case, list) and len(case) == 2 and all(isinstance(x, int) and -100 <= x <= 100 for x in case)

def solve(stdin):
    a, b = parse(stdin)
    return str(a + b)

def generate(seed, index, mode):
    if mode == "exhaustive":
        vals = list(range(-5, 6))
        if index >= len(vals) * len(vals):
            return None
        return [vals[index // len(vals)], vals[index % len(vals)]]
    import random
    rng = random.Random(seed + index)
    if mode == "adversarial":
        bounds = [-100, -1, 0, 1, 100]
        return [rng.choice(bounds), rng.choice(bounds)]
    return [rng.randint(-100, 100), rng.randint(-100, 100)]

def shrink(case):
    a, b = case
    res = []
    for na, nb in [(0, b), (a, 0), (int(a / 2), b), (a, int(b / 2)), (int(a / 2), int(b / 2))]:
        if [na, nb] != case and valid([na, nb]) and [na, nb] not in res:
            res.append([na, nb])
    return res[:16]

